config.command:
set -euo pipefail
BASE={{ project_path }}
cd "$BASE" || { echo 'frontend-metrics: Arbeitsverzeichnis nicht erreichbar'; exit 0; }
if [ ! -f scripts/public-readiness/frontend-metrics.sh ]; then
  echo '## summary'
  echo 'error=script_missing'
  exit 0
fi
# Reines Lesen, kein npm und kein node_modules — wenige Sekunden.
bash scripts/public-readiness/frontend-metrics.sh "$BASE" | awk '
  # ## packages (Verzeichniskanten) wertet keine Regel aus; Verzeichniskopplung steht in ## coupling.
  # ## files ist die vollstaendige Tabelle je Modul, ## recent die Aenderungen der letzten 7 Tage —
  # Eingaben der Einstufung und der Kandidatenwahl im Block arch_metrics.
  /^## / { inpk = ($0 == "## packages" || $0 == "## files" || $0 == "## recent") }
  inpk && $0 == "## packages" { print; print "# ausgelassen: Verzeichniskopplung steht in ## coupling"; next }
  inpk && $0 == "## files" { print; print "# ausgelassen: Tabelle je Modul, Eingabe der Einstufung (## findings im Block arch_metrics)"; next }
  inpk && $0 == "## recent" { print; print "# ausgelassen: Aenderungen der letzten 7 Tage, Eingabe von ## review_candidates im Block arch_metrics"; next }
  inpk && NF == 0 { print; next }
  inpk { next }
  { print }'
